def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    bal: dict[str, int] = {}
    frozen: set[str] = set()
    hist: list[tuple] = []
    rejected: list[int] = []

    def amount(tok: str):
        if tok and all(c in "0123456789" for c in tok):
            return int(tok)
        return None

    for i, op in enumerate(ops):
        parts = op.split(" ")
        verb = parts[0] if parts else ""
        ok = False
        if verb == "open" and len(parts) == 3:
            a, n = parts[1], amount(parts[2])
            if n is not None and a not in bal:
                bal[a] = n
                hist.append(("open", a))
                ok = True
        elif verb == "deposit" and len(parts) == 3:
            a, n = parts[1], amount(parts[2])
            if n is not None and n > 0 and a in bal:
                bal[a] += n
                hist.append(("deposit", a, n))
                ok = True
        elif verb == "withdraw" and len(parts) == 3:
            a, n = parts[1], amount(parts[2])
            if (
                n is not None
                and n > 0
                and a in bal
                and a not in frozen
                and bal[a] >= n
            ):
                bal[a] -= n
                hist.append(("withdraw", a, n))
                ok = True
        elif verb == "transfer" and len(parts) == 4:
            a, b, n = parts[1], parts[2], amount(parts[3])
            if (
                n is not None
                and n > 0
                and a != b
                and a in bal
                and b in bal
                and a not in frozen
                and bal[a] >= n
            ):
                bal[a] -= n
                bal[b] += n
                hist.append(("transfer", a, b, n))
                ok = True
        elif verb == "freeze" and len(parts) == 2:
            a = parts[1]
            if a in bal and a not in frozen:
                frozen.add(a)
                hist.append(("freeze", a))
                ok = True
        elif verb == "unfreeze" and len(parts) == 2:
            a = parts[1]
            if a in bal and a in frozen:
                frozen.remove(a)
                hist.append(("unfreeze", a))
                ok = True
        elif verb == "undo" and len(parts) == 1 and hist:
            rec = hist.pop()
            kind = rec[0]
            if kind == "open":
                del bal[rec[1]]
                frozen.discard(rec[1])
            elif kind == "deposit":
                bal[rec[1]] -= rec[2]
            elif kind == "withdraw":
                bal[rec[1]] += rec[2]
            elif kind == "transfer":
                bal[rec[2]] -= rec[3]
                bal[rec[1]] += rec[3]
            elif kind == "freeze":
                frozen.remove(rec[1])
            else:
                frozen.add(rec[1])
            ok = True
        if not ok:
            rejected.append(i)
    return bal, rejected
